parameters.jsCode:
const input = $input.item.json;
const remetente = $('ProcessaMensagem').first().json.remetente;
const buscaOriginal = $('ProcessaMensagem').first().json.busca_limpa;

// Campos e flags de resolucao vem do AplicaFiltrosResolvidos
const campos = input.campos || {};
const campos_resolvidos = input.campos_resolvidos || {};

const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};

// Persiste campos atualizados (sem sobrescrever campos_resolvidos e filtros_label)
if (!staticData.contextos[remetente]) staticData.contextos[remetente] = {};
staticData.contextos[remetente].campos_acumulados = campos;

function removerAcentos(str) {
  if (!str) return "";
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
}

const SINONIMOS = {
  "colegio": ["escola","educacional","ensino"],
  "escola": ["colegio","educacional","ensino"],
  "hospital": ["clinica","upa","saude"],
  "clinica": ["hospital","upa","saude"],
  "ubs": ["clinica","posto","saude"],
  "posto": ["ubs","clinica","saude"],
  "saude": ["hospital","clinica","ubs"],
  "creche": ["cei","infantil"],
  "cei": ["creche","infantil"],
  "estrada": ["rodovia","pavimentacao"],
  "rodovia": ["estrada","via","pavimentacao"],
  "ponte": ["viaduto","passarela"],
  "viaduto": ["ponte","passarela"],
  "policia": ["seguranca","delegacia"],
  "seguranca": ["policia","delegacia","bombeiro"],
  "bombeiro": ["seguranca","defesa"],
  "habitacao": ["moradia","casa","residencia"],
  "moradia": ["habitacao","casa","residencia"],
  "saneamento": ["esgoto","abastecimento"],
  "esgoto": ["saneamento","abastecimento"],
  "parque": ["praca","jardim"],
  "praca": ["parque","jardim"],
  "biblioteca": ["cultural","museu"],
  "ginasio": ["arena","estadio","quadra"],
  "estadio": ["ginasio","arena"]
};

function montarPattern(str) {
  if (!str || str === "QUALQUER") return null;
  const palavras = removerAcentos(str).toUpperCase().split(/\s+/).filter(function(w){ return w.length >= 3; });
  if (palavras.length === 0) return null;
  const palavrasUsadas = palavras.slice(0, 2);
  return "%" + palavrasUsadas.map(function(w){ return w.substring(0, 4); }).join("%") + "%";
}

function montarNomePatterns(str) {
  if (!str || str === "QUALQUER") return null;
  const palavras = removerAcentos(str).toLowerCase().split(/\s+/).filter(function(w){ return w.length >= 3; });
  if (palavras.length === 0) return null;
  const main = montarPattern(str);
  if (palavras.length !== 1) return [main];
  const extras = [];
  (SINONIMOS[palavras[0]] || []).forEach(function(sin) {
    const sinNorm = removerAcentos(sin).toUpperCase().substring(0, 4);
    const pat = "%" + sinNorm + "%";
    if (!extras.includes(pat) && pat !== main) extras.push(pat);
  });
  return [main].concat(extras);
}

function trNorm(col) {
  return "TRANSLATE(UPPER(" + col + "), 'AÁÀÂÃÄEÉÈÊËIÍÌÎÏOÓÒÔÕÖUÚÙÛÜÇ', 'AAAAAAEEEEEIIIIIOOOOOOUUUUUC')";
}

function escapeSql(str) {
  return (str || '').replace(/'/g, "''");
}

const busca_codigo = campos.codigo || "";
const busca_nome_patterns = montarNomePatterns(campos.nome);
const busca_nome_p = busca_nome_patterns ? busca_nome_patterns[0] : null;
const busca_municipio_p = montarPattern(campos.municipio);

// Orgao: usa = quando resolvido exatamente, LIKE caso contrário
const orgaoExato = campos_resolvidos.orgao === true && campos.orgao && campos.orgao !== 'QUALQUER';
const busca_orgao_p = orgaoExato ? null : montarPattern(campos.orgao);

// Tipo: usa = quando resolvido exatamente, LIKE caso contrário
const tipoExato = campos_resolvidos.tipo === true && campos.tipo && campos.tipo !== 'QUALQUER';
const busca_tipo_p = tipoExato ? null : montarPattern(campos.tipo);

const regiaoExato = campos_resolvidos.regiao === true && campos.regiao && campos.regiao !== 'QUALQUER';
const busca_regiao_p = regiaoExato ? null : montarPattern(campos.regiao);

const busca_situacao_p = montarPattern(campos.situacao);

// Monta WHERE principal
function nomeWhere(patterns) {
  if (!patterns || patterns.length === 0) return null;
  if (patterns.length === 1) return trNorm('VIP.NOME') + " LIKE '" + patterns[0] + "'";
  return "(" + patterns.map(function(p){ return trNorm('VIP.NOME') + " LIKE '" + p + "'"; }).join(" OR ") + ")";
}

let where;
if (busca_codigo) {
  const codigoNorm = busca_codigo.replace("/", "-");
  let whereCode;
  if (/^\d{1,6}-\d{4}$/.test(codigoNorm)) {
    // código completo: ex. 654-2024
    whereCode = "TRIM(TO_CHAR(VIP.NUMERO))||'-'||TRIM(TO_CHAR(VIP.ANO)) = '" + codigoNorm + "'";
  } else if (/^\d{1,6}$/.test(busca_codigo)) {
    // só o número, sem ano — retorna todos os anos para esse número
    whereCode = "VIP.NUMERO = " + parseInt(busca_codigo, 10);
  } else {
    whereCode = "1=0"; // código inválido
  }
  // Preserva filtro de município se já estava definido (evita perder contexto ao refinar)
  where = busca_municipio_p
    ? whereCode + " AND " + trNorm('M.MUNICIPIO') + " LIKE '" + busca_municipio_p + "'"
    : whereCode;
} else if (busca_nome_patterns && busca_municipio_p) {
  where = nomeWhere(busca_nome_patterns) + " AND " + trNorm('M.MUNICIPIO') + " LIKE '" + busca_municipio_p + "'";
} else if (busca_nome_patterns) {
  where = nomeWhere(busca_nome_patterns);
} else if (busca_municipio_p) {
  where = trNorm('M.MUNICIPIO') + " LIKE '" + busca_municipio_p + "'";
} else {
  where = "1=1";
}

// Filtros extras como AND
let whereExtra = "";
const situacaoExato = campos_resolvidos.situacao === true && campos.situacao && campos.situacao !== 'QUALQUER';
if (situacaoExato) {
  whereExtra += " AND " + trNorm('VIP.SITUACAO') + " = " + trNorm("'" + escapeSql(campos.situacao) + "'");
} else if (busca_situacao_p) {
  whereExtra += " AND " + trNorm('VIP.SITUACAO') + " LIKE '" + busca_situacao_p + "'";
}
// Sem filtro default de situacao — o fluxo de refinamento em ProcessaResultados
// pergunta sobre situacao quando ha muitos resultados
if (campos.ano && /^[0-9]{4}$/.test(campos.ano)) whereExtra += " AND VIP.ANO = " + campos.ano;

// Tipo: = exato ou LIKE fuzzy
if (tipoExato) {
  whereExtra += " AND " + trNorm('VIP.TIPO') + " = " + trNorm("'" + escapeSql(campos.tipo) + "'");
} else if (busca_tipo_p) {
  whereExtra += " AND " + trNorm('VIP.TIPO') + " LIKE '" + busca_tipo_p + "'";
}

// Orgao: = exato ou LIKE fuzzy
if (orgaoExato) {
  whereExtra += " AND " + trNorm('VIP.ORGAO') + " = " + trNorm("'" + escapeSql(campos.orgao) + "'");
} else if (busca_orgao_p) {
  whereExtra += " AND " + trNorm('VIP.ORGAO') + " LIKE '" + busca_orgao_p + "'";
}

if (regiaoExato) {
  whereExtra += " AND " + trNorm("BA.REGIAO") + " = " + trNorm("'" + escapeSql(campos.regiao) + "'");
} else if (busca_regiao_p) {
  whereExtra += " AND " + trNorm("BA.REGIAO") + " LIKE '" + busca_regiao_p + "'";
}

// Novos campos de VW_PROJETO_BUSCA_AVANCADA
if (campos.plano_governo === "Sim")  whereExtra += " AND BA.PLANO_GOVERNO = 'Sim'";
else if (campos.plano_governo === "Não") whereExtra += " AND (BA.PLANO_GOVERNO = 'Não' OR BA.PLANO_GOVERNO IS NULL)";
if (campos.prioridade && campos.prioridade !== "QUALQUER") {
  whereExtra += " AND " + trNorm("BA.PRIORIDADE") + " = " + trNorm("'" + escapeSql(campos.prioridade) + "'");
}
if (campos.programa && campos.programa !== "QUALQUER") {
  const progP = montarPattern(campos.programa);
  if (progP) whereExtra += " AND " + trNorm("BA.PROGRAMA_INVESTIMENTO") + " LIKE '" + progP + "'";
}
if (campos.setor && campos.setor !== "QUALQUER") {
  const setorP = montarPattern(campos.setor);
  if (setorP) whereExtra += " AND " + trNorm("BA.SETOR") + " LIKE '" + setorP + "'";
}
if (campos.associacao && campos.associacao !== "QUALQUER") {
  const assocP = montarPattern(campos.associacao);
  if (assocP) whereExtra += " AND " + trNorm("BA.ASSOCIACAO") + " LIKE '" + assocP + "'";
}

const whereCompleto = "(" + where + ")" + whereExtra;
const cteJoins = " FROM VW_IDENTIFICACAO_PROJETOS VIP LEFT JOIN LOCALIZACAO L ON L.PROJETO_ID = VIP.PROJETO_ID LEFT JOIN MUNICIPIO M ON M.ID = L.MUNICIPIO_ID LEFT JOIN VW_PROJETO_BUSCA_AVANCADA BA ON BA.ID = VIP.PROJETO_ID";
const sql = "WITH BASE AS (SELECT DISTINCT VIP.PROJETO_ID" + cteJoins + " WHERE " + whereCompleto + "), "
  + "MUNI_COUNTS AS (SELECT M.MUNICIPIO AS MC_MUN, COUNT(*) AS MC_CNT FROM BASE B JOIN VW_IDENTIFICACAO_PROJETOS VIP ON VIP.PROJETO_ID = B.PROJETO_ID LEFT JOIN LOCALIZACAO L ON L.PROJETO_ID = VIP.PROJETO_ID LEFT JOIN MUNICIPIO M ON M.ID = L.MUNICIPIO_ID GROUP BY M.MUNICIPIO), "
  + "TOTAL_COUNT AS (SELECT COUNT(*) AS TOTAL_GERAL FROM BASE), "
  + "SITUACAO_COUNTS AS (SELECT "
  + "COUNT(CASE WHEN " + trNorm('VIP.SITUACAO') + " LIKE '%CONCLU%' OR " + trNorm('VIP.SITUACAO') + " LIKE '%FINALIZ%' OR " + trNorm('VIP.SITUACAO') + " LIKE '%ENCERR%' THEN 1 END) AS TOTAL_CONCLUIDO, "
  + "COUNT(CASE WHEN NOT (" + trNorm('VIP.SITUACAO') + " LIKE '%CONCLU%' OR " + trNorm('VIP.SITUACAO') + " LIKE '%FINALIZ%' OR " + trNorm('VIP.SITUACAO') + " LIKE '%ENCERR%') THEN 1 END) AS TOTAL_ANDAMENTO "
  + "FROM BASE B JOIN VW_IDENTIFICACAO_PROJETOS VIP ON VIP.PROJETO_ID = B.PROJETO_ID) "
  + "SELECT VIP.PROJETO_ID, VIP.NUMERO, VIP.ANO, TRIM(TO_CHAR(VIP.NUMERO))||'-'||TRIM(TO_CHAR(VIP.ANO)) AS CODIGO_PROCESSO, VIP.NOME, VIP.SITUACAO, VIP.SITUACAO_ATUAL, VIP.ORGAO, VIP.TIPO, TO_CHAR(VIP.DATAINICIO, 'DD-MM-YYYY') AS DATA_INICIO, TO_CHAR(VIP.DATAFIM, 'DD-MM-YYYY') AS DATA_FIM, VIP.PRAZO_ESTIMADO AS PRAZOESTIMADO, VIP.VALORPLANEJADO, VIP.PERCEXECUTADOFINANC AS PERCENTUAL_EXEC, M.MUNICIPIO, MR.REGIAO, NVL(MC.MC_CNT, 0) AS TOTAL_MUNICIPIO, TC.TOTAL_GERAL, SC.TOTAL_CONCLUIDO, SC.TOTAL_ANDAMENTO, BA.PLANO_GOVERNO, BA.PRIORIDADE, BA.PROGRAMA_INVESTIMENTO, BA.SETOR, BA.ASSOCIACAO "
  + "FROM BASE B JOIN VW_IDENTIFICACAO_PROJETOS VIP ON VIP.PROJETO_ID = B.PROJETO_ID "
  + "LEFT JOIN LOCALIZACAO L ON L.PROJETO_ID = VIP.PROJETO_ID "
  + "LEFT JOIN MUNICIPIO M ON M.ID = L.MUNICIPIO_ID "
  + "LEFT JOIN MUNICIPIO_REGIAO MR ON MR.MUNICIPIO_ID = M.ID "
  + "LEFT JOIN VW_PROJETO_BUSCA_AVANCADA BA ON BA.ID = VIP.PROJETO_ID "
  + "LEFT JOIN MUNI_COUNTS MC ON MC.MC_MUN = M.MUNICIPIO "
  + "CROSS JOIN TOTAL_COUNT TC "
  + "CROSS JOIN SITUACAO_COUNTS SC "
  + "ORDER BY VIP.ANO DESC, VIP.NUMERO DESC FETCH FIRST 5000 ROWS ONLY";

const busca_limpa_completa = [campos.nome, campos.municipio, campos.situacao, campos.tipo, campos.orgao, campos.codigo, campos.ano, campos.prioridade, campos.programa, campos.setor, campos.associacao, campos.regiao]
  .filter(v => v && v !== "QUALQUER")
  .join(" ");

return [{
  remetente,
  busca_limpa: busca_limpa_completa || buscaOriginal,
  campos,
  sql_query: sql
}];

const todos = $input.all();
const remetente = $('ProcessaMensagem').first().json.remetente;
const staticData = $getWorkflowStaticData('global');
const contexto = staticData.contextos?.[remetente] || {};
const p = contexto.projeto_atual || {};

if (todos.length === 0) {
  return [{
    remetente,
    mensagem_retorno:
      "Ainda não há entregas registradas para esse projeto.\n\n" +
