const groqResp = $input.item.json;
const remetente = $('ProcessaMensagem').first().json.remetente;

const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};
const contexto = staticData.contextos[remetente] || {};
const agora = Date.now();

// Distintos em cache (armazenados pelo PreparaConsulta)
const distintos = staticData.filtrosDistintos || { orgaos: [], tipos: [], municipios: [], regioes: [], situacoes: [] };

// Quando é refinamento de seleção, não reprocessar campos via LLM
const buscaOriginal = $('ProcessaMensagem').first().json.busca_limpa;
let resolvido = {};
if (buscaOriginal !== 'refinar') {
  try {
    const texto = groqResp.choices[0].message.content.trim();
    resolvido = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch(e) {
    resolvido = {};
  }
}

// Aplicar valores resolvidos ao contexto (substitui vagos por exatos)
const campos = { ...(contexto.campos_acumulados || {}) };
const campos_resolvidos = { ...(contexto.campos_resolvidos || {}) };

function normalizar(s) {
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // remove diacríticos
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')    // remove pontos, parênteses, etc.
    .replace(/\s+/g, ' ')             // colapsa espaços
    .trim();
}

function encontrarExato(valor, lista) {
  if (!valor || valor === 'null' || valor === null) return null;
  const norm = normalizar(valor);
  if (!norm || norm.length < 2) return null;
  // 1. Match exato normalizado
  const exato = lista.find(v => normalizar(v) === norm);
  if (exato) return exato;
  // 2. Substring: termo do usuário aparece no nome do banco ("educacao" ⊂ "secretaria...educacao")
  const contem = lista.find(v => normalizar(v).includes(norm));
  if (contem) return contem;
  // 3. Multi-palavra: todas as palavras do usuário (≥3 chars) presentes no nome do banco
  const palavras = norm.split(' ').filter(p => p.length >= 3);
  if (palavras.length >= 2) {
    const multiWord = lista.find(v => {
      const vn = normalizar(v);
      return palavras.every(p => vn.includes(p));
    });
    if (multiWord) return multiWord;
  }
  // 4. Inverso: nome do banco contido no termo (fallback para siglas como "celesc")
  const inverso = lista.find(v => norm.includes(normalizar(v)) && normalizar(v).length >= 4);
  return inverso || null;
}

// ORGAO
if (resolvido.orgao && resolvido.orgao !== null) {
  const exato = encontrarExato(resolvido.orgao, distintos.orgaos);
  if (exato) {
    campos.orgao = exato;
    campos_resolvidos.orgao = true;
  } else if (!campos.orgao || campos.orgao === 'QUALQUER') {
    campos.orgao = resolvido.orgao; // mantém o vago como fallback
    campos_resolvidos.orgao = false;
  }
}

// TIPO
if (resolvido.tipo && resolvido.tipo !== null) {
  // Tenta match combinado tipo+nome primeiro (ex: "obra"+"rodoviaria" → "Obras Rodoviárias")
  // Preferir o match mais específico (mais longo) para evitar AND over-constrained
  const exatoSimples = encontrarExato(resolvido.tipo, distintos.tipos);
  const exatoCombo = resolvido.nome ? encontrarExato(resolvido.tipo + ' ' + resolvido.nome, distintos.tipos) : null;
  const exato = (exatoCombo && (!exatoSimples || exatoCombo.length > exatoSimples.length))
    ? exatoCombo
    : exatoSimples;
  if (exato) {
    campos.tipo = exato;
    campos_resolvidos.tipo = true;
    // Nome foi absorvido pelo tipo composto — descartá-lo para evitar filtro duplo
    if (exatoCombo && exato === exatoCombo) resolvido.nome = null;
  } else if (!campos.tipo || campos.tipo === 'QUALQUER') {
    // Tipo vago: descartar se nome cobre a mesma raiz (evita AND over-constrained)
    const tipoRaiz = normalizar(resolvido.tipo).split(' ')[0].substring(0, 4);
    const nomeRaiz = normalizar(resolvido.nome || campos.nome || '').split(' ')[0].substring(0, 4);
    const tipoCobertoPorNome = tipoRaiz.length >= 3 && nomeRaiz.length >= 3 &&
      (tipoRaiz.startsWith(nomeRaiz) || nomeRaiz.startsWith(tipoRaiz));
    if (!tipoCobertoPorNome) {
      campos.tipo = resolvido.tipo;
      campos_resolvidos.tipo = false;
    }
  }
}

// MUNICIPIO (mantém LIKE, só normaliza capitalização)
if (resolvido.municipio && resolvido.municipio !== null) {
  const exato = encontrarExato(resolvido.municipio, distintos.municipios);
  if (exato) {
    campos.municipio = exato;
    campos_resolvidos.municipio = true;
  } else if (!campos.municipio || campos.municipio === 'QUALQUER') {
    campos.municipio = resolvido.municipio;
    campos_resolvidos.municipio = false;
  }
}

// REGIAO
if (resolvido.regiao && resolvido.regiao !== null) {
  const exatoReg = encontrarExato(resolvido.regiao, distintos.regioes);
  if (exatoReg) {
    campos.regiao = exatoReg;
    campos_resolvidos.regiao = true;
  } else if (!campos.regiao || campos.regiao === 'QUALQUER') {
    campos.regiao = resolvido.regiao;
    campos_resolvidos.regiao = false;
  }
}

// NOME: preservar exatamente como retornado
if (resolvido.nome && resolvido.nome !== null && !campos.nome) {
  campos.nome = resolvido.nome;
}

// Se tipo foi resolvido exatamente e nome é redundante (palavras do nome já estão
// dentro do valor do tipo), descartar nome para evitar AND over-constrained.
// Ex: tipo="Obras Rodoviárias" + nome="rodoviaria" → descarta nome.
if (campos_resolvidos.tipo === true && campos.tipo && campos.nome) {
  const tipoNorm = normalizar(campos.tipo);
  const nomePalavras = normalizar(campos.nome).split(' ').filter(p => p.length >= 4);
  if (nomePalavras.length > 0 && nomePalavras.every(p => tipoNorm.includes(p))) {
    delete campos.nome;
  }
}

// ANO: número puro, sem validação de lista
if (resolvido.ano && resolvido.ano !== null) {
  const anoNum = parseInt(resolvido.ano, 10);
  if (anoNum >= 1990 && anoNum <= 2030) {
    campos.ano = String(anoNum);
  }
}

// CODIGO: pass-through direto (ex: "654" ou "654/2024")
if (resolvido.codigo && resolvido.codigo !== null) {
  campos.codigo = String(resolvido.codigo).trim();
}

// Campos de VW_PROJETO_BUSCA_AVANCADA — pass-through direto
if (resolvido.plano_governo !== null && resolvido.plano_governo !== undefined) {
  // Guardrail: só aceita plano_governo do LLM se o usuário mencionou explicitamente "plano" ou "governo"
  const texPGGuard = normalizar(buscaOriginal);
  if (texPGGuard.includes('plano') || texPGGuard.includes('governo')) {
    const pg = String(resolvido.plano_governo).trim().toLowerCase();
    if (pg === 'sim' || pg === 's' || pg === 'true')                          campos.plano_governo = "Sim";
    else if (pg === 'não' || pg === 'nao' || pg === 'n' || pg === 'false') campos.plano_governo = "Não";
  }
}

// SITUACAO — resolve exato contra lista do banco quando disponível
if (resolvido.situacao && resolvido.situacao !== null) {
  const exatoSit = encontrarExato(resolvido.situacao, distintos.situacoes || []);
  if (exatoSit) {
    campos.situacao = exatoSit;
    campos_resolvidos.situacao = true;
  } else if (!campos.situacao || campos.situacao === 'QUALQUER') {
    campos.situacao = resolvido.situacao;
    campos_resolvidos.situacao = false;
  }
}
// Override determinístico: detecta negação/afirmação de plano de governo no texto original
// Necessário porque o LLM frequentemente ignora a negação e extrai só o conceito base
if (buscaOriginal && buscaOriginal !== 'refinar') {
  const _texPG = buscaOriginal.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (/plano\s+de\s+governo/.test(_texPG)) {
    campos.plano_governo = /\b(nao|sem|exceto|nenhum)\b/.test(_texPG) ? 'Não' : 'Sim';
  }
}
if (resolvido.prioridade && resolvido.prioridade !== null) campos.prioridade = resolvido.prioridade;
if (resolvido.programa   && resolvido.programa   !== null && !campos.programa)   campos.programa   = resolvido.programa;
if (resolvido.setor      && resolvido.setor      !== null && !campos.setor)      campos.setor      = resolvido.setor;
if (resolvido.associacao && resolvido.associacao !== null && !campos.associacao) campos.associacao = resolvido.associacao;

// Descarte pós-LLM: se nome é apenas palavras de introdução + município já resolvido,
// o nome é redundante e deve ser removido para evitar filtro desnecessário.
// Ex: nome="Projetos Palhoça" + municipio="Palhoça" → descarta nome.
if (campos.nome && campos.municipio) {
  const INTRO = ['projeto', 'projetos', 'lista', 'mostre', 'quais'];
  let resto = normalizar(campos.nome);
  INTRO.forEach(w => { resto = resto.replace(new RegExp('\\b' + w + '\\b', 'g'), ''); });
  resto = resto.replace(normalizar(campos.municipio), '').replace(/\s+/g, '').trim();
  if (resto.length < 3) delete campos.nome;
}

// Detecção direta de palavras-chave no texto original (fallback quando LLM falha)
const buscaNorm = normalizar(buscaOriginal);
if (/plano\s+(de\s+)?governo/.test(buscaNorm)) {
  campos.plano_governo = /\b(nao|sem|exceto|nenhum)\b/.test(buscaNorm) ? 'Não' : 'Sim';
  // Remove do nome se o LLM classificou errado
  if (campos.nome) {
    const nomeNorm = normalizar(campos.nome);
    if (nomeNorm.includes("plano") && nomeNorm.includes("governo")) delete campos.nome;
  }
}

// Gerar filtros_label legível
function abreviarOrgao(orgao) {
  return (orgao || '')
    .replace('Secretaria de Estado da ', 'Sec. de ')
    .replace('Secretaria de Estado de ', 'Sec. de ')
    .replace('Secretaria de Estado do ', 'Sec. do ')
    .replace('Secretaria de Estado dos ', 'Sec. dos ')
    .replace('Fundação Catarinense', 'FC')
    .replace('Departamento Estadual de', 'DE');
}

const partes = [];
if (campos.municipio && campos.municipio !== 'QUALQUER') partes.push('Município: ' + campos.municipio);
if (campos.regiao    && campos.regiao    !== 'QUALQUER') partes.push('Região: '    + campos.regiao);
if (campos.orgao     && campos.orgao     !== 'QUALQUER') partes.push('Órgão: ' + abreviarOrgao(campos.orgao));
if (campos.situacao  && campos.situacao  !== 'QUALQUER') partes.push('Situação: ' + campos.situacao);
if (campos.tipo      && campos.tipo      !== 'QUALQUER') partes.push('Tipo: ' + campos.tipo);
if (campos.nome      && campos.nome      !== 'QUALQUER') partes.push('Nome: ' + campos.nome);
if (campos.ano) partes.push('Ano: ' + campos.ano);
if (campos.plano_governo === 'Sim') partes.push('Plano de Governo: Sim');
if (campos.plano_governo === 'Não') partes.push('Plano de Governo: Não');
if (campos.prioridade  && campos.prioridade  !== 'QUALQUER') partes.push('Prioridade: ' + campos.prioridade);
if (campos.programa    && campos.programa    !== 'QUALQUER') partes.push('Programa: ' + campos.programa);
if (campos.setor       && campos.setor       !== 'QUALQUER') partes.push('Setor: ' + campos.setor);
if (campos.associacao  && campos.associacao  !== 'QUALQUER') partes.push('Associação: ' + campos.associacao);

const filtros_label = partes.length > 0
  ? '\uD83D\uDD0D *Filtros:* ' + partes.join(' | ')
  : '';

// Atualizar contexto
contexto.campos_acumulados = campos;
contexto.campos_resolvidos = campos_resolvidos;
contexto.filtros_label = filtros_label;
contexto.ultimaInteracao = agora;
staticData.contextos[remetente] = contexto;

return [{
  remetente,
  campos,
  campos_resolvidos,
  filtros_label,
  busca_limpa: $('PreparaConsulta').first().json.busca_limpa || '',
  campos_faltantes: []
}];

const input = $input.item.json;
const remetente = input.remetente;
const mensagemRetorno = input.mensagem_retorno;

const pergunta = $('AplicaClassificacao').first().json.pergunta || '';

let respostaLLM = mensagemRetorno;
try {
  respostaLLM = $('RespondePerguntas').first().json.choices[0].message.content.trim();
} catch(e) {}

const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};
if (!staticData.contextos[remetente]) staticData.contextos[remetente] = {};
const contexto = staticData.contextos[remetente];
if (!contexto.historico_qa) contexto.historico_qa = [];

contexto.historico_qa.push({ role: 'user', content: pergunta });
contexto.historico_qa.push({ role: 'assistant', content: respostaLLM });

if (contexto.historico_qa.length > 8) {
  contexto.historico_qa = contexto.historico_qa.slice(-8);
}
staticData.contextos[remetente] = contexto;

return [{ remetente, mensagem_retorno: mensagemRetorno }];

// Story 1.27 — NormalizaEntrada
// Inserido entre PreparaConsulta e InterpretaConsulta
