const REGIOES = {
  'grande floripa':       'Florianópolis, São José, Palhoça, Biguaçu, São Pedro de Alcântara',
  'grande fpolis':        'Florianópolis, São José, Palhoça, Biguaçu, São Pedro de Alcântara',
