  'meio oeste':           'Caçador, Videira, Joaçaba',
};

const MOEDA = [
  { re: /(\d+(?:[.,]\d+)?)\s*(?:bilhões?|bilhao|bilhão|bi\b)/i, mult: 1000000000 },
  { re: /(\d+(?:[.,]\d+)?)\s*(?:milhões?|milhao|milhão|mi\b)/i, mult: 1000000 },
  { re: /(\d+(?:[.,]\d+)?)\s*(?:mil\b|k\b)/i, mult: 1000 },
  { re: /meio\s+bilh[aã]o/i, replacement: 'R$ 500.000.000' },
  { re: /meio\s+milh[aã]o/i, replacement: 'R$ 500.000' },
];

function normRegioes(t) {
  let r = t;
  for (const [a, m] of Object.entries(REGIOES))
    r = r.replace(new RegExp(a, 'gi'), m);
  return r;
}

function normMunicipios(t) {
  let r = t;
  for (const [p, o] of Object.entries(MUNICIPIOS))
    r = r.replace(new RegExp('\\b' + p + '\\b', 'gi'), o);
  return r;
}

function normMonetario(t) {
  let r = t;
  for (const { re, mult, replacement } of MOEDA) {
    if (replacement) { r = r.replace(re, replacement); }
    else { r = r.replace(re, (_, n) => 'R$ ' + (parseFloat(n.replace(',','.')) * mult).toLocaleString('pt-BR')); }
  }
  return r;
}

function normalizar(t) { return normMonetario(normMunicipios(normRegioes(t))); }

const resultado = [];
for (const item of $input.all()) {
  const original = item.json.busca_limpa || '';
  const normalizado = normalizar(original);
  resultado.push({
    json: {
      ...item.json,
      busca_limpa: normalizado,
      busca_pre_normalizacao: original !== normalizado ? original : undefined,
    }
  });
}
return resultado;

