// Story 1.25 — FormataFallback
const EMOJIS = ['1️⃣','2️⃣','3️⃣'];

function extrairSugestoes(content) {
  if (!content) return [];
  try {
    const p = JSON.parse(content);
    if (Array.isArray(p)) return p.slice(0,3).filter(Boolean);
  } catch(_) {
    const linhas = content.split('\n').filter(l => /^\d+[\.\)]\s+/.test(l.trim()));
    if (linhas.length > 0) return linhas.slice(0,3).map(l => l.replace(/^\d+[\.\)]\s+/,'').trim());
    const csv = content.split(',').map(s=>s.trim()).filter(Boolean);
    if (csv.length >= 2) return csv.slice(0,3);
  }
  return [];
}

const resultado = [];
for (const item of $input.all()) {
  const remetente   = item.json.remetente;
  const busca       = item.json.busca_original || '';
  const groqContent = item.json.choices?.[0]?.message?.content || '';
  const sugestoes   = extrairSugestoes(groqContent);

  let mensagem;
  if (sugestoes.length > 0) {
    const opts = sugestoes.map((s,i) => `${EMOJIS[i]||`${i+1}.`} ${s}`).join('\n');
    mensagem = `Não encontrei nada com *"${busca}"*. 🤔\n\nQue tal tentar de outro jeito?\n\n${opts}\n\n0️⃣ Nova busca livre`;
  } else {
    mensagem = `Não encontrei nada com *"${busca}"*. 😕\n\nTente o nome da cidade, categoria da obra, número do projeto ou nome da empresa.\n\n0️⃣ Nova busca`;
  }
  resultado.push({ json:{ tipo:'sem_resultado', mensagem_retorno:mensagem, remetente } });
}
return resultado;

// VerificaConfianca — apenas lógica, sem HTTP (task runner não permite)
const THRESHOLD = 0.70;
const LABEL = {
  busca: 'Buscar um projeto',
  saudacao: 'Saudação / início',
  submenu_entregas: 'Ver entregas do projeto',
  submenu_valores: 'Ver valores do projeto',
  submenu_contratos: 'Ver contratos do projeto',
  pergunta_livre: 'Fazer uma pergunta sobre o projeto',
};

const item = $input.item.json;
const confidence   = typeof item.confidence === 'number' ? item.confidence : 1.0;
const alternatives = Array.isArray(item.alternatives) ? item.alternatives : [];

// Alta confiança ou sem alternativas → passa direto
if (confidence >= THRESHOLD || alternatives.length === 0) {
  return [{ passthrough: true, ...item }];
}

// Baixa confiança → preparar mensagem de confirmação (HTTP feito pelo próximo nó)
const opcao1 = item.tipo;
const opcao2 = alternatives[0];
const mensagem =
  `Hm, não tenho certeza do que você quer. 🤔\n\n` +
  `1️⃣ ${LABEL[opcao1] || opcao1}\n2️⃣ ${LABEL[opcao2] || opcao2}\n\nQual é a sua intenção?`;

// Salvar estado no staticData
const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};
const ctx = staticData.contextos[item.remetente] || {};
ctx.aguardando_confirmacao = {
  opcao1, opcao2,
  busca_original: item.busca_limpa || '',
  campos_opcao1: item.campos_acumulados || {},
  expira_em: Date.now() + 3 * 60 * 1000,
};
staticData.contextos[item.remetente] = ctx;

return [{ passthrough: false, remetente: item.remetente, mensagem_retorno: mensagem }];
